    fun getCategories() {
        viewModelScope.launch {
            shopRepository.getCategoryList().collect { resource ->
                when (resource) {
                    is Resource.GenericError -> {
                        sendMessage(resource.message)
                    }
                    is Resource.Loading -> {
                        setLoading(resource.loading)
                    }
                    is Resource.NetworkError -> {
                        setApiErrors(resource.response.apply {
                            (this.uiComponentType as UIComponentType.RetryApiDialog).callback = object : BinaryActionCallback {
                                override fun yes() {
                                    getCategories()
                                }

                                override fun no() {}
                            }
                        })
                    }
                    is Resource.Success -> {
                        resource.data?.data?.let {
                            //_popularProduct.postValue(it)
                            _categoryData.postValue(it.category)
                            _banner1.postValue(it.banner1)
                            _banner2.postValue(it.banner2)
                            _sliderBanners.postValue(it.slider)
                        }
                    }
                }
            }
        }
    }

